<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Plan } from '~/types/billing'
import { money } from '~/utils/billing'
definePageMeta({ layout: 'admin', middleware: 'superadmin' })
const { request } = useApi()
const { data, pending, error, refresh } = await useAsyncData('admin-plans', () => request<ApiEnvelope<Plan[]>>('management/plans'))
const editing = ref(false), selected = ref<number | null>(null), saving = ref(false), failure = ref(''), message = ref('')
const form = reactive({ name:'', slug:'', description:'', currency:'USD', monthly:'', yearly:'', limit:'', features:'', is_active:true, is_public:true, sort_order:0, stripe_monthly_price_id:'', stripe_yearly_price_id:'' })
function edit(plan?: Plan) {
  selected.value = plan?.id || null
  Object.assign(form, { name:plan?.name || '', slug:plan?.slug || '', description:plan?.description || '', currency:plan?.currency || 'USD', monthly:plan?.monthly_price == null?'':String(plan.monthly_price/100), yearly:plan?.yearly_price == null?'':String(plan.yearly_price/100), limit:plan?.link_limit == null?'':String(plan.link_limit), features:plan?.features.join('\n') || '', is_active:plan?.is_active ?? true, is_public:plan?.is_public ?? true, sort_order:plan?.sort_order ?? 0, stripe_monthly_price_id:plan?.stripe_monthly_price_id || '', stripe_yearly_price_id:plan?.stripe_yearly_price_id || '' })
  failure.value=''; editing.value=true
}
async function save() {
  saving.value=true; failure.value=''
  try {
    await request(`management/plans${selected.value?`/${selected.value}`:''}`, { method:selected.value?'PUT':'POST', body:{ name:form.name, slug:form.slug, description:form.description, currency:form.currency, monthly_price:form.monthly===''?null:Math.round(Number(form.monthly)*100), yearly_price:form.yearly===''?null:Math.round(Number(form.yearly)*100), link_limit:form.limit===''?null:Number(form.limit), features:form.features.split('\n').map(v=>v.trim()).filter(Boolean), is_active:form.is_active, is_public:form.is_public, sort_order:form.sort_order, stripe_monthly_price_id:form.stripe_monthly_price_id || null, stripe_yearly_price_id:form.stripe_yearly_price_id || null } })
    editing.value=false; message.value='Plan saved. Existing subscription prices are preserved.'; await refresh()
  } catch(e:any) { failure.value=Object.values(e?.data?.errors || {}).flat().join(' ') || e?.data?.message || 'Unable to save plan.' } finally { saving.value=false }
}
</script>
<template><div><div class="flex justify-between gap-4"><div><p class="eyebrow">Your product catalog</p><h1 class="page-title mt-2">Plans & pricing</h1><p class="mt-2 text-text-secondary">One source of truth for your public pricing and customer subscriptions.</p></div><button class="btn-primary" @click="edit()">+ New plan</button></div><p v-if="message" class="mt-6 rounded-lg bg-success-bg p-4 text-success" role="status">{{ message }}</p><LoadingState v-if="pending"/><p v-else-if="error" class="mt-8" role="alert">Unable to load plans. <button class="text-brand" @click="refresh()">Retry</button></p><div v-else class="mt-8 grid gap-5 lg:grid-cols-3"><article v-for="plan in data?.data" :key="plan.id" class="surface flex flex-col p-6"><div class="flex justify-between"><h2 class="text-xl font-semibold">{{ plan.name }}</h2><span :class="plan.is_active?'badge-success':'badge-warning'">{{ plan.is_active?'Active':'Archived' }}</span></div><p class="mt-3 min-h-10 text-sm text-text-secondary">{{ plan.description }}</p><p class="mt-6 text-3xl font-bold">{{ money(plan.monthly_price,plan.currency) }}<span v-if="plan.monthly_price!==null" class="text-xs font-normal text-text-muted"> / month</span></p><p class="mt-2 text-xs text-text-muted">Yearly: {{ money(plan.yearly_price,plan.currency) }}</p><div class="my-5 border-y border-border py-4 text-sm"><p>{{ plan.link_limit===null?'Unlimited':plan.link_limit }} total links</p><p class="mt-1 text-text-muted">{{ plan.is_public?'Visible on pricing page':'Private plan' }}{{ plan.is_default?' · Default plan':'' }}</p></div><ul class="mb-6 flex-1 space-y-2 text-sm text-text-secondary"><li v-for="feature in plan.features" :key="feature">✓ {{ feature }}</li></ul><button class="btn-secondary w-full" @click="edit(plan)">Edit plan</button></article></div><AdminDialog v-if="editing" :title="selected?'Edit plan':'Create plan'" @close="editing=false"><form class="grid gap-4" @submit.prevent="save"><div class="grid grid-cols-2 gap-4"><label class="label">Plan name<input v-model="form.name" class="input mt-2" maxlength="100" required></label><label class="label">Slug<input v-model="form.slug" class="input mt-2" pattern="[A-Za-z0-9_-]+" required></label></div><label class="label">Description<textarea v-model="form.description" class="input mt-2" maxlength="500"/></label><div class="grid grid-cols-3 gap-3"><label class="label">Currency<select v-model="form.currency" class="input mt-2"><option v-for="currency in ['USD','EUR','GBP','BDT']" :key="currency">{{ currency }}</option></select></label><label class="label">Monthly price<input v-model="form.monthly" class="input mt-2" type="number" min="0" step="0.01" placeholder="Custom"></label><label class="label">Yearly price<input v-model="form.yearly" class="input mt-2" type="number" min="0" step="0.01" placeholder="Custom"></label></div><div class="grid grid-cols-2 gap-4"><label class="label">Total link limit<input v-model="form.limit" class="input mt-2" type="number" min="1" placeholder="Unlimited"></label><label class="label">Display order<input v-model.number="form.sort_order" class="input mt-2" type="number" min="0" max="999"></label></div><label class="label">Features · one per line<textarea v-model="form.features" class="input mt-2" rows="4" required/></label><div class="flex gap-5"><label class="flex gap-2 text-sm"><input v-model="form.is_active" type="checkbox">Active</label><label class="flex gap-2 text-sm"><input v-model="form.is_public" type="checkbox">Show on public pricing</label></div><details class="rounded-lg border border-border p-4"><summary class="cursor-pointer text-sm font-medium">Stripe price mapping</summary><p class="my-3 text-xs text-text-muted">After enabling Stripe, link recurring Price IDs with matching amounts and currency. Leave empty for manual subscriptions.</p><label class="label">Monthly Price ID<input v-model="form.stripe_monthly_price_id" class="input mt-2" placeholder="price_…"></label><label class="label mt-3">Yearly Price ID<input v-model="form.stripe_yearly_price_id" class="input mt-2" placeholder="price_…"></label></details><p v-if="failure" role="alert" class="text-sm text-danger">{{ failure }}</p><button class="btn-primary" :disabled="saving">{{ saving?'Saving…':'Save plan' }}</button></form></AdminDialog></div></template>
